import{z as A,x as n,o as e,c as s,q as t,j as l,D as o,d as r,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"套刻控制回路","description":"","frontmatter":{"title":"套刻控制回路","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/overlay-control-loop.md","filePath":"litho/overlay-control-loop.md","lastUpdated":1791063341000}'),p={name:"litho/overlay-control-loop.md"};function h(d,a,c,C,D,_){const E=n("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="套刻控制回路" tabindex="-1">套刻控制回路 <a class="header-anchor" href="#套刻控制回路" aria-label="Permalink to &quot;套刻控制回路&quot;">​</a></h1><div class="epigraph"><p>套刻回路把对准读数和套刻计量变成下一场的网格；它控的是层对层位移，不是 CD，更不是把光学热点补进平移项。</p><footer>—— 对照 ASML 对 overlay control / holistic lithography 的公开论述</footer></div><p><a href="/litho/spc-control-chart">上一课</a>把残差判异写清。缺口是套刻这条环的专用执行器：场间线性、场内高阶、扫描偏扭。<a href="/litho/litho-overlay">套刻 Overlay</a> 与预算课已定义量；本课钉回路，高阶场内项如何开，留给<a href="/litho/high-order-field-correction">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回路输入：对准（曝光前，本片）、套刻计量（曝光后，常是上批或本批抽样）。输出：扫描机网格校正、有时掩模台。前馈：本片对准看见的晶圆膨胀/旋转。反馈：上批套刻残差更新机台指纹。两者混用时要避免把对准噪声写进长期指纹。</p><p>缺口是<strong>时间与对象</strong>，不是再选 DBO。关键对准树决定量的是哪一对；回路必须按对配置，不能全厂一张 overlay APC。混机（后课 tool-to-tool）时，指纹要分机存储。</p>',6)),(e(),l(i,null,{default:o(()=>[B(E,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%22%E6%89%B9%E6%AC%A1%20N%3A%20%E6%9B%9D%E5%85%89%22%5D%20--%3E%20B2%5B%22%E8%AE%A1%E9%87%8F%3A%20%E9%87%8F%E5%A5%97%E5%88%BB%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E6%9B%B4%E6%96%B0%E6%9C%BA%E5%8F%B0%E6%8C%87%E7%BA%B9%20%2F%20%E9%99%90%E5%B9%85%22%5D%0A%20%20B3%20--%3E%20B4%5B%22%E6%89%B9%E6%AC%A1%20N%2B1%3A%20%E7%94%A8%E6%96%B0%E7%BD%91%E6%A0%BC%E6%9B%9D%E5%85%89%22%5D%0A%20%20B4%20--%3E%20B5%7B%22%E6%AE%8B%E5%B7%AE%E8%BF%9B%E8%A7%84%E6%A0%BC%3F%22%7D%0A%20%20B5%20--%3E%7C%22%E6%98%AF%22%7C%20HOLD%5B%22%E7%BB%B4%E6%8C%81%E6%8C%87%E7%BA%B9%20%E6%8C%81%E7%BB%AD%E7%9B%91%E6%8E%A7%22%5D%0A%20%20B5%20--%3E%7C%22%E5%90%A6%22%7C%20ALARM%5B%22%E5%88%A4%E5%BC%82%3A%20%E5%81%9C%E7%BA%BF%20%2F%20%E5%89%A5%E8%83%B6%E9%87%8D%E6%9B%9D%20%2F%20%E6%A0%87%E8%AE%B0%E6%8C%87%E7%BA%B9%E4%B8%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20B5%20--%3E%20B1%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：这条环像开长途车的「微调方向盘」——每跑一段（一批）看一眼偏离车道多少（计量），小幅回正（更新指纹），而不是等冲出路面再猛打方向。术语翻译：R2R（run-to-run）控制就是「一批一调」的节奏；调幅受限幅压着，防止把一次计量噪声当成真漂移，一把打过中线。</span></p><h3 id="不要用平移去补光学" tabindex="-1">不要用平移去补光学 <a class="header-anchor" href="#不要用平移去补光学" aria-label="Permalink to &quot;不要用平移去补光学&quot;">​</a></h3><p>CD 热点、镜头像差、加热引起的场内 CD 不对称，不是套刻回路的活。用 overlay 平移去「对齐」一个失焦的孔，会让整场器件错位。 holistic 叙事里 CD 与套刻是耦合预算，但执行器仍要配对。</p><p><span class="marginnote">计量到曝光的延迟内，卡盘热和批次温度会变。回路模型应含「过期读数」的降权，而不是假装网格冻结。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置：每关键对独立控制器、限幅、与抽样点数匹配的项。曝光前对准做本片前馈；曝光后套刻做机台/产品反馈。与 YieldStar 一类机内计量：缩短延迟，仍要抽样计划。与重工：套刻失败是否剥胶重曝，属分派课，但回路应标记「不可用指纹」。</p><p>holistic lithography 的公开叙事把 CD 与套刻放在同一预算里，但扫描机上仍是两套执行器。本课要求两套环的状态机分开，只在预算报表上相加。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>网格是多项式（或扫描仪等价项）作用在场坐标上。对准给本片系数的测量；套刻给「器件对」的事后真理。标记–器件偏置是慢变量，可进反馈，不可当本片噪声。热瞬态使同一批前后片系数滑移，R2R 节拍要细于热时间常数，或在批内做分段。</p>',9)),(e(),l(i,null,{default:o(()=>[B(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALN%5B%22%E6%9C%AC%E7%89%87%E5%AF%B9%E5%87%86%22%5D%20--%3E%20FF%5B%22%E6%9C%AC%E7%89%87%E7%BD%91%E6%A0%BC%E5%89%8D%E9%A6%88%22%5D%0A%20%20OVL%5B%22%E4%B8%8A%E6%89%B9%E5%A5%97%E5%88%BB%22%5D%20--%3E%20FB%5B%22%E6%9C%BA%E5%8F%B0%E6%8C%87%E7%BA%B9%E5%8F%8D%E9%A6%88%22%5D%0A%20%20FF%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%E7%BD%91%E6%A0%BC%22%5D%0A%20%20FB%20--%3E%20EXP%0A%20%20PAIR%5B%22%E5%85%B3%E9%94%AE%E5%B1%82%E5%AF%B9%22%5D%20--%3E%20FB%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>本片对准前馈与上批套刻反馈键在同一关键对上。用平移项去补失焦孔，会把整场器件错位。</p><p><span class="marginnote">为什么重要：前馈和反馈若混着用，对准传感器的随机噪声会被当成真实漂移写进长期指纹，指纹从此「记错账」，之后每一批都带着这个偏差走。常见误区是以为回路越敏感越好——实际上把噪声也放大进执行器，网格会批间震荡。回路设计的一半功夫在决定「什么不该信」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>回路不修设计规则冲突。不重写高阶多项式全文（下一课）。不把 ASML 未公开的控制带宽写成数字。</p><p>后课默认：套刻按层对闭环，对准前馈 + 计量反馈。下一课只开抽样支撑得住的场内高阶项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>套刻回路配对网格执行器，按关键对分实例。</li><li>本片对准前馈，事后套刻反馈指纹。</li><li>禁止用平移项去补 CD/焦点问题。</li><li>出处：ASML overlay control 公开论述；holistic lithography 公开叙事。</li></ul>',7))])}const f=A(p,[["render",h]]);export{u as __pageData,f as default};
